mapper.select:
SELECT a.id AS "id", a.name AS "name", a.person_type AS "personType", a.gender AS "gender", o.office_name AS "company", p.position_name AS "department", wg.work_group_name AS "team", f.work_type AS "jobType", a.safety_helmet_id AS "safetyHelmetId", a.personnel_status AS "personnelStatus", a.safety_education AS "safetyEducation", a.identity_card AS "identityCard", a.phone_number AS "phoneNumber", a.helmet_returned AS "helmetReturned", a.departure_type AS "departureType", a.departure_reason AS "departureReason", a.departure_date AS "departureDate", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks", a.status AS "status" FROM ${sqlMap.table.toSql()} LEFT JOIN fms_worker f ON a.identity_card = f.identity_code COLLATE utf8mb4_general_ci LEFT JOIN js_sys_office o ON f.office_code = o.office_code AND o.zip_code IS NOT NULL LEFT JOIN fms_position_archive p ON f.work_shop_code = p.id AND p.type = 'CJ' LEFT JOIN fms_work_group wg ON f.work_group_id = wg.id
${sqlMap.where.toSql()}
ORDER BY ${sqlMap.order.toSql()}
